import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
export default class RoomJoinModal extends Modal {
  password = '';
  loading = false;
  className() {
    return 'Modal--small SocialRoomJoinModal';
  }
  title() {
    return app.translator.trans('cengizkemec-social.forum.rooms.password_title');
  }
  content() {
    return m('div', {
      className: 'Modal-body'
    }, m('form', {
      onsubmit: event => {
        event.preventDefault();
        this.loading = true;
        this.attrs.onjoin?.(this.password);
        this.hide();
      }
    }, [m('p', {}, app.translator.trans('cengizkemec-social.forum.rooms.password_text')), m('div', {
      className: 'Form-group'
    }, m('input', {
      className: 'FormControl',
      type: 'password',
      value: this.password,
      oninput: event => this.password = event.target.value,
      autofocus: true
    })), m(Button, {
      className: 'Button Button--primary Button--block',
      type: 'submit',
      loading: this.loading
    }, app.translator.trans('cengizkemec-social.forum.voice.join'))]));
  }
}
flarum.reg.add('cengizkemec-social', 'forum/components/RoomJoinModal', RoomJoinModal);